{"command":"cd /Users/dev/horizon/apps/bff
cat > probe.ts <<'EOF'
import { BanyanDBClient } from './src/client/banyandb/index.js';
const c = new BanyanDBClient({ kind: 'banyandb', address: '127.0.0.1:27912', deadlineMs: 15000 });
await c.connect();
const ns = `probe_${Date.now().toString(36)}`;
await c.reconcileGroup({ name: ns, catalog: 'CATALOG_STREAM', shardNum: 1,
  segmentInterval: { unit: 'UNIT_DAY', num: 1 }, ttl: { unit: 'UNIT_DAY', num: 3 }, replicas: 0 });
const def = { group: ns, name: 'log', entity: ['principal'],
  families: [{ name: 'searchable', tags: [{ name: 'principal', type: 'TAG_TYPE_STRING' as const }] }] };
await c.reconcileStream(def);
const now = Date.now();
const out = await c.insertStream(def, [{ timestampMs: now, elementId: 'e1', tags: { principal: 'alice' } }]);
console.log('NS=' + ns);
console.log('NOW=' + now);
console.log('WRITE=' + JSON.stringify(out));
c.close();
EOF
OUT=$(timeout 300 npx tsx probe.ts 2>&1 | tail -3); echo "$OUT"
NS=$(echo "$OUT" | grep '^NS=' | cut -d= -f2); NOW=$(echo "$OUT" | grep '^NOW=' | cut -d= -f2)
sleep 2 2>/dev/null || true
echo "=== query the SAME data over BanyanDB's own HTTP gateway ==="
timeout 60 curl -s -m 20 -X POST "http://127.0.0.1:27913/api/v1/stream/data" \
  -H 'Content-Type: application/json' \
  -d "{\"groups\":[\"$NS\"],\"name\":\"log\",\"timeRange\":{\"begin\":\"$(python3 -c "import datetime,sys;print(datetime.datetime.utcfromtimestamp((int(sys.argv[1])-3600000)/1000).strftime('%Y-%m-%dT%H:%M:%S.000Z'))" $NOW)\",\"end\":\"$(python3 -c "import datetime,sys;print(datetime.datetime.utcfromtimestamp((int(sys.argv[1])+3600000)/1000).strftime('%Y-%m-%dT%H:%M:%S.000Z'))" $NOW)\"},\"projection\":{\"tagFamilies\":[{\"name\":\"searchable\",\"tags\":[\"principal\"]}]},\"limit\":10}" 2>&1 | head -c 900","description":"Query the client-written data via BanyanDB
